const form = $('Sleeper Bench Court Form').first().json ?? {};
const leagueId = String(form.leagueId ?? '').trim();
const week = Number(form.week);
if (!leagueId || leagueId.length > 128) throw new Error('Enter a valid Sleeper league ID.');
if (!Number.isInteger(week) || week < 1 || week > 18) throw new Error('Week must be a whole number from 1 to 18.');
return [{ json: { leagueId, week, submittedAt: form.submittedAt ?? new Date().toISOString() } }];

const form = $('Sleeper Bench Court Form').first().json ?? {};
const league = $('Get League Settings').first().json ?? {};
const users = $('Get League Managers').all().map((item) => item.json ?? {});
const rosters = $('Get League Rosters').all().map((item) => item.json ?? {});
const matchups = $('Get Week Matchups').all().map((item) => item.json ?? {});
const playerMap = $('Get Active Player Map').first().json ?? {};

const leagueId = String(form.leagueId ?? '').trim();
const week = Number(form.week);
const generatedAt = new Date().toISOString();

const finite = (value, fallback = 0) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
};

const round = (value, digits = 2) => {
  const power = 10 ** digits;
  return Math.round((finite(value) + Number.EPSILON) * power) / power;
};

const escapeHtml = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');

const usersById = new Map(
  users
    .filter((user) => user.user_id !== null && user.user_id !== undefined)
    .map((user) => [String(user.user_id), user]),
);

const rostersById = new Map(
  rosters
    .filter((roster) => roster.roster_id !== null && roster.roster_id !== undefined)
    .map((roster) => [String(roster.roster_id), roster]),
);

const teamNameForRoster = (rosterId) => {
  const roster = rostersById.get(String(rosterId));
  const owner = roster ? usersById.get(String(roster.owner_id)) : null;
  return (
    owner?.metadata?.team_name ||
    owner?.metadata?.team_name_update ||
    owner?.display_name ||
    (rosterId !== null && rosterId !== undefined ? `Roster ${rosterId}` : 'Unknown roster')
  );
};

const playerFor = (playerId) => playerMap[String(playerId)] ?? {};

const playerName = (playerId) => {
  const player = playerFor(playerId);
  return (
    player.full_name ||
    [player.first_name, player.last_name].filter(Boolean).join(' ') ||
    String(playerId)
  );
};

const playerPositions = (playerId) => {
  const player = playerFor(playerId);
  const positions = Array.isArray(player.fantasy_positions)
    ? player.fantasy_positions
    : [player.position];
  return new Set(positions.filter(Boolean).map((position) => String(position).toUpperCase()));
};

const inactiveSlots = new Set(['BN', 'IR', 'TAXI', 'RESERVE']);
const starterSlots = (Array.isArray(league.roster_positions) ? league.roster_positions : [])
  .map((slot) => String(slot).toUpperCase())
  .filter((slot) => !inactiveSlots.has(slot));

const slotFamilies = {
  FLEX: ['RB', 'WR', 'TE'],
  'W/R/T': ['RB', 'WR', 'TE'],
  WRT: ['RB', 'WR', 'TE'],
  REC_FLEX: ['WR', 'TE'],
  'W/T': ['WR', 'TE'],
  WRRB_FLEX: ['WR', 'RB'],
  'W/R': ['WR', 'RB'],
  SUPER_FLEX: ['QB', 'RB', 'WR', 'TE'],
  'Q/W/R/T': ['QB', 'RB', 'WR', 'TE'],
  IDP_FLEX: ['DL', 'DE', 'DT', 'LB', 'DB', 'CB', 'S'],
  'DL/LB/DB': ['DL', 'DE', 'DT', 'LB', 'DB', 'CB', 'S'],
};

const canFill = (playerId, slot) => {
  const positions = playerPositions(playerId);
  if (positions.has(slot)) return true;
  const family = slotFamilies[slot];
  return Array.isArray(family) && family.some((position) => positions.has(position));
};

const addEdge = (graph, from, to, capacity, cost, metadata = null) => {
  const forward = { to, rev: graph[to].length, capacity, cost, metadata };
  const reverse = { to: from, rev: graph[from].length, capacity: 0, cost: -cost, metadata: null };
  graph[from].push(forward);
  graph[to].push(reverse);
};

const optimizeLineup = (record) => {
  const points = record.players_points && typeof record.players_points === 'object'
    ? record.players_points
    : {};
  const playerIds = [...new Set([
    ...(Array.isArray(record.players) ? record.players : []),
    ...Object.keys(points),
  ].filter((id) => id !== null && id !== undefined).map(String))];

  const playerCount = playerIds.length;
  const slotCount = starterSlots.length;
  const source = 0;
  const playerOffset = 1;
  const slotOffset = playerOffset + playerCount;
  const sink = slotOffset + slotCount;
  const graph = Array.from({ length: sink + 1 }, () => []);

  playerIds.forEach((playerId, playerIndex) => {
    const playerNode = playerOffset + playerIndex;
    addEdge(graph, source, playerNode, 1, 0);
    starterSlots.forEach((slot, slotIndex) => {
      if (!canFill(playerId, slot)) return;
      const score = finite(points[playerId]);
      addEdge(
        graph,
        playerNode,
        slotOffset + slotIndex,
        1,
        -Math.round(score * 1000),
        { playerId, slot, slotIndex, score },
      );
    });
  });

  starterSlots.forEach((_, slotIndex) => {
    addEdge(graph, slotOffset + slotIndex, sink, 1, 0);
  });

  let flow = 0;
  let cost = 0;
  while (flow < slotCount) {
    const distance = Array(graph.length).fill(Number.POSITIVE_INFINITY);
    const previousNode = Array(graph.length).fill(-1);
    const previousEdge = Array(graph.length).fill(-1);
    distance[source] = 0;

    for (let pass = 0; pass < graph.length - 1; pass += 1) {
      let changed = false;
      for (let nodeIndex = 0; nodeIndex < graph.length; nodeIndex += 1) {
        if (!Number.isFinite(distance[nodeIndex])) continue;
        graph[nodeIndex].forEach((edge, edgeIndex) => {
          if (edge.capacity <= 0) return;
          const candidate = distance[nodeIndex] + edge.cost;
          if (candidate >= distance[edge.to]) return;
          distance[edge.to] = candidate;
          previousNode[edge.to] = nodeIndex;
          previousEdge[edge.to] = edgeIndex;
          changed = true;
        });
      }
      if (!changed) break;
    }

    if (previousNode[sink] === -1) break;
    for (let nodeIndex = sink; nodeIndex !== source; nodeIndex = previousNode[nodeIndex]) {
      const from = previousNode[nodeIndex];
      const edge = graph[from][previousEdge[nodeIndex]];
      edge.capacity -= 1;
      graph[nodeIndex][edge.rev].capacity += 1;
      cost += edge.cost;
    }
    flow += 1;
  }

  const assignments = [];
  playerIds.forEach((_, playerIndex) => {
    const playerNode = playerOffset + playerIndex;
    for (const edge of graph[playerNode]) {
      if (!edge.metadata || edge.capacity !== 0) continue;
      assignments.push(edge.metadata);
    }
  });

  const actualStarters = (Array.isArray(record.starters) ? record.starters : [])
    .filter((id) => id !== null && id !== undefined && String(id) !== '0')
    .map(String);
  const actualFromPlayers = actualStarters.reduce(
    (total, playerId) => total + finite(points[playerId]),
    0,
  );
  const actual = Number.isFinite(Number(record.points)) ? Number(record.points) : actualFromPlayers;
  const calculatedOptimal = -cost / 1000;
  const optimal = Math.max(calculatedOptimal, actual);
  const pointsLeft = Math.max(0, optimal - actual);
  const optimalIds = new Set(assignments.map((assignment) => assignment.playerId));
  const actualIds = new Set(actualStarters);

  const benchHeroes = assignments
    .filter((assignment) => !actualIds.has(assignment.playerId))
    .sort((a, b) => b.score - a.score);
  const regrettedStarters = actualStarters
    .filter((playerId) => !optimalIds.has(playerId))
    .map((playerId) => ({ playerId, score: finite(points[playerId]) }))
    .sort((a, b) => a.score - b.score);

  const swaps = benchHeroes.slice(0, 3).map((benchPlayer, index) => {
    const starter = regrettedStarters[index];
    return {
      in: playerName(benchPlayer.playerId),
      inPoints: round(benchPlayer.score),
      slot: benchPlayer.slot,
      out: starter ? playerName(starter.playerId) : null,
      outPoints: starter ? round(starter.score) : null,
    };
  });

  return {
    rosterId: String(record.roster_id ?? ''),
    matchupId: record.matchup_id,
    teamName: teamNameForRoster(record.roster_id),
    actual: round(actual),
    optimal: round(optimal),
    pointsLeft: round(pointsLeft),
    efficiency: optimal > 0 ? round((actual / optimal) * 100, 1) : 100,
    swaps,
    filledSlots: flow,
    totalSlots: slotCount,
  };
};

const teamResults = matchups.map(optimizeLineup);
const matchupGroups = new Map();
for (const team of teamResults) {
  const key = team.matchupId === null || team.matchupId === undefined
    ? `bye-${team.rosterId}`
    : String(team.matchupId);
  if (!matchupGroups.has(key)) matchupGroups.set(key, []);
  matchupGroups.get(key).push(team);
}

const games = [...matchupGroups.entries()]
  .map(([matchupId, teams]) => {
    const ordered = [...teams].sort((a, b) => b.actual - a.actual);
    const first = ordered[0] ?? null;
    const second = ordered[1] ?? null;
    const margin = first && second ? round(Math.abs(first.actual - second.actual)) : null;
    let benchedWin = null;
    if (first && second && first.actual !== second.actual && second.optimal > first.actual) {
      benchedWin = {
        teamName: second.teamName,
        missedBy: round(second.optimal - first.actual),
      };
    }
    return { matchupId, teams: ordered, margin, benchedWin };
  })
  .sort((a, b) => finite(a.margin, 999999) - finite(b.margin, 999999));

const byPointsLeft = [...teamResults].sort((a, b) => b.pointsLeft - a.pointsLeft);
const byEfficiency = [...teamResults].sort((a, b) => b.efficiency - a.efficiency);
const byActual = [...teamResults].sort((a, b) => b.actual - a.actual);
const benchConvict = byPointsLeft[0] ?? null;
const lineupValedictorian = byEfficiency[0] ?? null;
const highScorer = byActual[0] ?? null;
const closestGame = games.find((game) => game.teams.length === 2) ?? null;
const benchedWins = games.filter((game) => game.benchedWin);
const totalPointsLeft = round(teamResults.reduce((total, team) => total + team.pointsLeft, 0));
const incompleteLineups = teamResults.filter((team) => team.filledSlots < team.totalSlots).length;

const verdict = (team) => {
  if (team.pointsLeft < 0.01) return 'Clean lineup';
  if (team.pointsLeft <= 5) return 'Minor lineup misdemeanor';
  if (team.pointsLeft <= 15) return 'Questionable coaching';
  return 'Bench felony';
};

const awardCard = (icon, title, team, detail) => `
  <article class="award">
    <div class="award-icon">${escapeHtml(icon)}</div>
    <div>
      <span>${escapeHtml(title)}</span>
      <strong>${escapeHtml(team || 'Not available')}</strong>
      <small>${escapeHtml(detail || '')}</small>
    </div>
  </article>`;

const matchupHtml = games.map((game) => {
  const sides = game.teams.map((team, index) => {
    const winner = game.teams.length === 2 && index === 0 && game.teams[0].actual !== game.teams[1].actual;
    const swapText = team.swaps.length
      ? team.swaps.map((swap) =>
          `${escapeHtml(swap.in)} (${swap.inPoints})${swap.out ? ` over ${escapeHtml(swap.out)} (${swap.outPoints})` : ''}`,
        ).join('<br>')
      : 'No better eligible bench swap found.';
    return `
      <section class="team ${winner ? 'winner' : ''}">
        <header><span>${winner ? '🏆' : '🏈'}</span><h3>${escapeHtml(team.teamName)}</h3></header>
        <div class="score">${team.actual.toFixed(2)}</div>
        <div class="metrics">
          <span><b>${team.optimal.toFixed(2)}</b> optimal</span>
          <span><b>${team.efficiency.toFixed(1)}%</b> efficient</span>
          <span><b>${team.pointsLeft.toFixed(2)}</b> benched</span>
        </div>
        <p class="verdict">${escapeHtml(verdict(team))}</p>
        <details><summary>Best lineup changes</summary><p>${swapText}</p></details>
      </section>`;
  }).join('');

  const ruling = game.benchedWin
    ? `<div class="ruling guilty">⚖️ ${escapeHtml(game.benchedWin.teamName)} benched a win by ${game.benchedWin.missedBy.toFixed(2)} points.</div>`
    : game.teams.length === 2
      ? `<div class="ruling">Final margin: ${finite(game.margin).toFixed(2)} points.</div>`
      : '<div class="ruling">No paired opponent was returned for this roster.</div>';

  return `<article class="matchup"><div class="teams">${sides}</div>${ruling}</article>`;
}).join('');

const rankingRows = [...teamResults]
  .sort((a, b) => b.pointsLeft - a.pointsLeft)
  .map((team, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${escapeHtml(team.teamName)}</td>
      <td>${team.actual.toFixed(2)}</td>
      <td>${team.optimal.toFixed(2)}</td>
      <td>${team.pointsLeft.toFixed(2)}</td>
      <td>${team.efficiency.toFixed(1)}%</td>
      <td>${escapeHtml(verdict(team))}</td>
    </tr>`).join('');

const leagueName = league.name || `Sleeper League ${leagueId}`;

const reportHtml = `
<style>
  :root{color-scheme:dark;--color-background:#070a14;--color-card-bg:#070a14;--color-card-border:#070a14;--color-card-shadow:transparent;--ink:#f8fafc;--muted:#a5b4fc;--panel:#111827;--line:#312e81;--accent:#e5ff39;--danger:#fb7185;--purple:#4338ca}
  html,body{min-height:100%;background:#070a14!important}body{margin:0!important}.container{width:100%!important;max-width:none!important;padding:0!important;margin:0!important;text-align:left!important}.card{padding:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:#070a14!important;margin:0!important}
  *{box-sizing:border-box}.court{position:relative;max-width:1180px;min-height:100vh;margin:0 auto;padding:28px 18px 60px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}
  .hero{padding:34px;border:1px solid #4f46e5;border-radius:24px;background:radial-gradient(circle at top right,rgba(229,255,57,.18),transparent 28rem),linear-gradient(135deg,#1e1b4b,#111827 68%);box-shadow:0 24px 70px rgba(0,0,0,.35)}
  .eyebrow{text-transform:uppercase;letter-spacing:.14em;color:var(--accent);font-weight:800;font-size:12px}.hero h1{font-size:clamp(34px,6vw,68px);line-height:.95;margin:10px 0 16px;letter-spacing:-.05em}.hero p{color:#c7d2fe;max-width:760px;font-size:17px;line-height:1.6}
  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-top:24px}.stat{padding:16px;border-radius:16px;background:rgba(17,24,39,.76);border:1px solid #3730a3}.stat b{display:block;font-size:25px;color:var(--accent)}.stat span{color:#c7d2fe;font-size:13px}
  .court h2{color:var(--ink);font-size:28px;margin:38px 0 16px;letter-spacing:-.03em}.awards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.award{display:flex;gap:14px;padding:18px;border-radius:18px;background:linear-gradient(145deg,#111827,#0d1324);border:1px solid var(--line);box-shadow:0 12px 30px rgba(0,0,0,.18)}.award-icon{font-size:30px}.award span,.award small{display:block;color:var(--muted);font-size:12px}.award strong{display:block;margin:4px 0;font-size:18px;line-height:1.25}
  .matchup{margin:18px 0;border:1px solid var(--line);border-radius:20px;overflow:hidden;background:#0b1020}.teams{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}.team{padding:22px;border-right:1px solid var(--line)}.team:last-child{border-right:0}.team.winner{background:linear-gradient(180deg,rgba(229,255,57,.08),transparent)}.team header{display:flex;align-items:center;gap:9px}.team h3{margin:0;font-size:19px}.score{font-size:45px;font-weight:900;letter-spacing:-.05em;margin:14px 0}.metrics{display:flex;flex-wrap:wrap;gap:8px}.metrics span{padding:7px 9px;border-radius:999px;background:#1f2937;color:#c7d2fe;font-size:12px}.metrics b{color:#fff}.verdict{color:var(--accent);font-weight:800}.team details{color:#c7d2fe}.team summary{cursor:pointer}.team details p{line-height:1.6}.ruling{padding:14px 20px;background:#1e1b4b;color:#c7d2fe;font-weight:700}.ruling.guilty{background:rgba(251,113,133,.14);color:#fecdd3}
  .table-wrap{overflow:auto;border:1px solid var(--line);border-radius:18px}table{width:100%;border-collapse:collapse;background:var(--panel)}th,td{padding:13px 15px;text-align:left;border-bottom:1px solid #272f45;white-space:nowrap}th{color:var(--accent);font-size:12px;text-transform:uppercase;letter-spacing:.08em}td{color:#dbeafe}.note{margin-top:28px;padding:18px;border-left:4px solid var(--accent);background:#111827;color:#c7d2fe;line-height:1.6}.footer{margin-top:24px;color:#818cf8;font-size:12px}
  @media(max-width:640px){.hero{padding:24px}.team{border-right:0;border-bottom:1px solid var(--line)}.court{padding:16px 8px 40px}}
</style>
<main class="court">
  <section class="hero">
    <div class="eyebrow">Sleeper Bench Court · Week ${escapeHtml(week)}</div>
    <h1>${escapeHtml(leagueName)}</h1>
    <p>The evidence has been entered. Bench Court compares each submitted lineup with the highest-scoring legal lineup available from that roster's recorded weekly players.</p>
    <div class="stats">
      <div class="stat"><b>${teamResults.length}</b><span>teams reviewed</span></div>
      <div class="stat"><b>${totalPointsLeft.toFixed(2)}</b><span>points left on benches</span></div>
      <div class="stat"><b>${benchedWins.length}</b><span>results that could flip</span></div>
      <div class="stat"><b>${escapeHtml(generatedAt.slice(0, 10))}</b><span>ruling generated</span></div>
    </div>
  </section>

  <h2>Weekly awards</h2>
  <section class="awards">
    ${awardCard('🚔', 'Bench Felony', benchConvict?.teamName, benchConvict ? `${benchConvict.pointsLeft.toFixed(2)} points left behind` : '')}
    ${awardCard('🎓', 'Lineup Valedictorian', lineupValedictorian?.teamName, lineupValedictorian ? `${lineupValedictorian.efficiency.toFixed(1)}% efficient` : '')}
    ${awardCard('🔥', 'High Score', highScorer?.teamName, highScorer ? `${highScorer.actual.toFixed(2)} actual points` : '')}
    ${awardCard('📸', 'Photo Finish', closestGame?.teams.map((team) => team.teamName).join(' vs '), closestGame ? `${finite(closestGame.margin).toFixed(2)}-point margin` : '')}
  </section>

  <h2>Matchup rulings</h2>
  ${matchupHtml || '<div class="note">No matchup records were returned for this league and week.</div>'}

  <h2>Bench accountability ranking</h2>
  <div class="table-wrap">
    <table>
      <thead><tr><th>#</th><th>Team</th><th>Actual</th><th>Optimal</th><th>Benched</th><th>Efficiency</th><th>Verdict</th></tr></thead>
      <tbody>${rankingRows || '<tr><td colspan="7">No teams returned.</td></tr>'}</tbody>
    </table>
  </div>

  <div class="note">
    <strong>How the ruling works:</strong> Bench Court uses the league's configured starter slots and each player's Sleeper fantasy-position eligibility. It solves a maximum-score legal assignment across QB, RB, WR, TE, K, DEF, FLEX, SUPER_FLEX, REC_FLEX, WRRB_FLEX, and common IDP slots. It evaluates recorded weekly points only; it does not claim a manager could have predicted those results before kickoff.
    ${incompleteLineups ? `<br><strong>Review note:</strong> ${incompleteLineups} roster(s) did not have enough recognized position data to fill every configured slot, so their actual score was retained as the minimum optimal score.` : ''}
  </div>
  <div class="footer">Generated with the unofficial, read-only n8n-nodes-sleeper community node. Sleeper data remains public and belongs to its respective owners. This project is not affiliated with or endorsed by Sleeper.</div>
</main>`;

return [{
  json: {
    reportHtml,
    leagueId,
    leagueName,
    week,
    generatedAt,
    summary: {
      teamsReviewed: teamResults.length,
      matchupsReviewed: games.length,
      totalPointsLeft,
      benchedWins: benchedWins.length,
      incompleteLineups,
    },
  },
}];
